<?php
require_once __DIR__ . '/../config/config.php';
require_once __DIR__ . '/../helpers/auth.php';
require_once __DIR__ . '/../helpers/permissions_v2.php';
require_once __DIR__ . '/../helpers/csrf.php';
require_once __DIR__ . '/../services/HealthEncounterService.php';

require_login();
$actorUserId=(int)($_SESSION['user_id']??0);$actorChurchId=(int)($_SESSION['church_id']??0);$superAdmin=is_super_admin();
if($actorChurchId<=0&&$actorUserId>0){$stmt=$conn->prepare('SELECT church_id FROM users WHERE id=?');$stmt->bind_param('i',$actorUserId);$stmt->execute();$actorChurchId=(int)($stmt->get_result()->fetch_assoc()['church_id']??0);$stmt->close();}
$service=new HealthEncounterService($conn,$actorUserId,$actorChurchId,$superAdmin);
$id=max(0,(int)($_GET['id']??$_POST['record_id']??0));$record=$service->getRecord($id);
if(!$record||!$service->authorize('view_health_records',(int)$record['church_id'])){http_response_code(404);exit('Health encounter not found.');}
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['void_record'])){
 if(!csrf_is_valid($_POST['csrf_token']??null)){$error='Your session token expired.';}else{try{$service->void($id,(string)($_POST['void_reason']??''));header('Location: health_records.php?id='.$id.'&voided=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}
}
$record=$service->getRecord($id);
if(isset($_GET['saved']))$message='Health encounter saved successfully.';if(isset($_GET['voided']))$message='Health encounter voided; the evidence remains in the audit trail.';
$canEdit=$record['status']!=='voided'&&$service->authorize('edit_health_record',(int)$record['church_id']);
$canVoid=$record['status']!=='voided'&&$service->authorize('void_health_record',(int)$record['church_id']);

$personWhere=$record['member_id']?'history.member_id=?':'history.sundayschool_id=?';$personId=(int)($record['member_id']?:$record['sundayschool_id']);
$historyStmt=$conn->prepare("SELECT history.id,history.recorded_at,history.status,history.encounter_type,history.follow_up_status,history.notes,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=history.id AND observation_code='weight' LIMIT 1) weight,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=history.id AND observation_code='temperature' LIMIT 1) temperature,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=history.id AND observation_code='blood_pressure_systolic' LIMIT 1) systolic,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=history.id AND observation_code='blood_pressure_diastolic' LIMIT 1) diastolic,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=history.id AND observation_code='blood_glucose' LIMIT 1) glucose
 FROM health_records history WHERE {$personWhere} AND history.church_id=? ORDER BY history.recorded_at DESC,history.id DESC LIMIT 50");
$historyStmt->bind_param('ii',$personId,$record['church_id']);$historyStmt->execute();$history=$historyStmt->get_result();$historyRows=[];while($row=$history->fetch_assoc())$historyRows[]=$row;$historyStmt->close();
$auditStmt=$conn->prepare('SELECT audit.action,audit.reason,audit.created_at,user.name actor_name FROM health_record_audit audit LEFT JOIN users user ON user.id=audit.changed_by_user_id WHERE audit.health_record_id=? ORDER BY audit.created_at DESC,audit.id DESC');$auditStmt->bind_param('i',$id);$auditStmt->execute();$audits=$auditStmt->get_result();
$definitions=HealthEncounterService::observationDefinitions();
$chartRows=array_reverse(array_filter($historyRows,fn($row)=>$row['status']!=='voided'));
$page_title='Health Encounter';ob_start();
?>
<link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/health-workspace.css">
<div class="container-fluid health-workspace py-3">
 <div class="health-hero mb-4 d-flex flex-wrap justify-content-between align-items-center"><div><h1><i class="fas fa-file-medical-alt mr-2"></i>Health encounter</h1><p><?= htmlspecialchars($record['full_name']) ?> · <?= htmlspecialchars($record['identifier']) ?> · <?= date('d M Y, g:i A',strtotime($record['recorded_at'])) ?></p></div><div class="no-print mt-2 mt-md-0"><a href="health_list.php" class="btn btn-light"><i class="fas fa-arrow-left"></i></a><?php if($canEdit):?> <a href="health_form.php?id=<?= $id ?>" class="btn btn-light"><i class="fas fa-pen mr-1"></i> Correct</a><?php endif;?> <button onclick="window.print()" class="btn btn-light"><i class="fas fa-print mr-1"></i> Print</button></div></div>
 <?php if($message):?><div class="alert alert-success health-alert"><?= htmlspecialchars($message) ?></div><?php endif;?><?php if($error):?><div class="alert alert-danger health-alert"><?= htmlspecialchars($error) ?></div><?php endif;?>
 <?php if($record['status']==='voided'):?><div class="alert alert-secondary health-alert"><strong>Voided encounter.</strong> <?= htmlspecialchars($record['void_reason']??'') ?></div><?php endif;?>
 <div class="row mb-4"><div class="col-lg-8 mb-3 mb-lg-0"><div class="health-panel h-100"><div class="health-panel-header"><div><h2 class="health-section-title">Encounter overview</h2><p class="health-section-copy">Finalized clinical evidence and care context.</p></div><span class="status-pill <?= htmlspecialchars($record['status']) ?>"><?= htmlspecialchars(ucfirst($record['status'])) ?></span></div><div class="health-panel-body">
  <div class="health-person mb-4"><img class="health-avatar" src="<?= BASE_URL ?>/assets/img/undraw_profile.svg" alt=""><div><div class="health-person-name"><?= htmlspecialchars($record['full_name']) ?></div><div class="health-person-meta"><?= htmlspecialchars($record['identifier']) ?> · <?= htmlspecialchars(ucfirst(str_replace('_',' ',$record['person_type']))) ?><?= $record['dob']?' · '.(int)(new DateTimeImmutable($record['dob']))->diff(new DateTimeImmutable('today'))->y.' years':'' ?></div></div></div>
  <div class="metric-grid"><?php foreach($record['observations'] as $code=>$observation):$definition=$definitions[$code]??['label'=>ucwords(str_replace('_',' ',$code)),'unit'=>$observation['unit_code']??''];?><div class="metric-card"><div class="metric-label"><?= htmlspecialchars($definition['label']) ?></div><div class="h4 mb-1"><?= htmlspecialchars(rtrim(rtrim(number_format((float)$observation['value_numeric'],3,'.',''),'0'),'.')) ?> <small class="text-muted"><?= htmlspecialchars($observation['unit_code']??$definition['unit']) ?></small></div><?php if(($observation['interpretation']??'unknown')==='attention'):?><span class="status-pill attention"><i class="fas fa-flag"></i> Verify / follow up</span><?php endif;?><?php if(!empty($observation['measurement_context'])):?><div class="small text-muted mt-1"><?= htmlspecialchars(ucfirst(str_replace('_',' ',$observation['measurement_context']))) ?></div><?php endif;?></div><?php endforeach;?></div>
  <?php if(!$record['observations']):?><div class="health-empty py-3">No structured measurements were recorded.</div><?php endif;?>
 </div></div></div>
 <div class="col-lg-4"><div class="health-panel h-100"><div class="health-panel-header"><h2 class="health-section-title">Care plan</h2></div><div class="health-panel-body"><dl class="row small"><dt class="col-5">Type</dt><dd class="col-7"><?= htmlspecialchars(ucfirst(str_replace('_',' ',$record['encounter_type']))) ?></dd><dt class="col-5">Follow-up</dt><dd class="col-7"><span class="status-pill"><?= htmlspecialchars(ucfirst($record['follow_up_status'])) ?></span></dd><dt class="col-5">Due</dt><dd class="col-7"><?= $record['follow_up_date']?date('d M Y',strtotime($record['follow_up_date'])):'—' ?></dd><dt class="col-5">Referral</dt><dd class="col-7"><?= htmlspecialchars($record['referral_destination']?:'—') ?></dd><dt class="col-5">Recorded by</dt><dd class="col-7"><?= htmlspecialchars($record['recorded_by_name']?:'Unknown') ?></dd></dl><?php if($record['notes']):?><hr><div class="small font-weight-bold mb-1">Notes</div><div class="small text-muted"><?= nl2br(htmlspecialchars($record['notes'])) ?></div><?php endif;?></div></div></div></div>
 <div class="health-panel mb-4"><div class="health-panel-header"><div><h2 class="health-section-title">Screening results</h2><p class="health-section-copy">Results do not replace clinical interpretation or confirmatory testing.</p></div></div><div class="health-panel-body"><div class="row"><?php foreach(['malaria'=>'Malaria','hepatitis_b'=>'Hepatitis B'] as $code=>$label):$screen=$record['screenings'][$code]??null;?><div class="col-md-6 mb-2"><div class="metric-card"><div class="metric-label"><?= $label ?></div><?php if($screen):?><span class="status-pill <?= htmlspecialchars($screen['result_code']) ?>"><?= htmlspecialchars(ucfirst(str_replace('_',' ',$screen['result_code']))) ?></span><?php if(!empty($screen['method'])):?><div class="small text-muted mt-2">Method: <?= htmlspecialchars($screen['method']) ?></div><?php endif;?><?php else:?><span class="text-muted">Not recorded</span><?php endif;?></div></div><?php endforeach;?></div></div></div>
 <div class="health-panel mb-4"><div class="health-panel-header"><div><h2 class="health-section-title">Longitudinal trends</h2><p class="health-section-copy">Up to 50 recent, non-voided encounters. Gaps mean the measurement was not taken.</p></div></div><div class="health-panel-body"><canvas id="healthTrend" height="80"></canvas></div></div>
 <div class="row"><div class="col-lg-8 mb-4"><div class="health-panel"><div class="health-panel-header"><h2 class="health-section-title">Visit history</h2><span class="status-pill"><?= count($historyRows) ?> visits</span></div><div class="table-responsive"><table class="table health-table mb-0"><thead><tr><th>Date</th><th>Type</th><th>BP</th><th>Temp</th><th>Glucose</th><th></th></tr></thead><tbody><?php foreach($historyRows as $visit):?><tr><td><?= date('d M Y',strtotime($visit['recorded_at'])) ?><div><span class="status-pill <?= $visit['status'] ?>"><?= htmlspecialchars($visit['status']) ?></span></div></td><td><?= htmlspecialchars(ucfirst(str_replace('_',' ',$visit['encounter_type']))) ?></td><td><?= $visit['systolic']!==null?(int)$visit['systolic'].'/'.(int)$visit['diastolic']:'—' ?></td><td><?= $visit['temperature']!==null?number_format((float)$visit['temperature'],1).'°C':'—' ?></td><td><?= $visit['glucose']!==null?number_format((float)$visit['glucose'],1):'—' ?></td><td><a class="btn btn-sm btn-outline-info" href="health_records.php?id=<?= $visit['id'] ?>"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div></div></div>
 <div class="col-lg-4 mb-4"><div class="health-panel"><div class="health-panel-header"><h2 class="health-section-title">Audit trail</h2></div><div class="health-panel-body"><?php if($audits->num_rows===0):?><div class="text-muted small">Legacy encounter; no modern audit events yet.</div><?php endif;?><?php while($audit=$audits->fetch_assoc()):?><div class="border-left pl-3 mb-3"><div class="font-weight-bold small"><?= htmlspecialchars(ucfirst(str_replace('_',' ',$audit['action']))) ?></div><div class="small text-muted"><?= date('d M Y, g:i A',strtotime($audit['created_at'])) ?> · <?= htmlspecialchars($audit['actor_name']?:'System') ?></div><div class="small"><?= htmlspecialchars($audit['reason']) ?></div></div><?php endwhile;?></div></div>
 <?php if($canVoid):?><div class="health-panel mt-3 no-print"><div class="health-panel-body"><button class="btn btn-outline-danger btn-sm" data-toggle="collapse" data-target="#voidForm"><i class="fas fa-ban mr-1"></i> Void encounter</button><form method="post" class="collapse mt-3" id="voidForm"><?= csrf_input() ?><input type="hidden" name="record_id" value="<?= $id ?>"><input type="hidden" name="void_record" value="1"><label class="font-weight-bold small">Reason</label><textarea class="form-control mb-2" name="void_reason" minlength="8" maxlength="500" required></textarea><button class="btn btn-danger btn-sm" onclick="return confirm('Void this encounter? It will remain in the audit trail.')">Confirm void</button></form></div></div><?php endif;?></div></div>
</div>
<script>
(function(){const canvas=document.getElementById('healthTrend');if(!canvas||typeof Chart==='undefined')return;new Chart(canvas.getContext('2d'),{type:'line',data:{labels:<?= json_encode(array_map(fn($r)=>date('d M y',strtotime($r['recorded_at'])),$chartRows)) ?>,datasets:[{label:'Systolic',data:<?= json_encode(array_map(fn($r)=>$r['systolic']!==null?(float)$r['systolic']:null,$chartRows)) ?>,borderColor:'#087f8c',fill:false,spanGaps:true},{label:'Diastolic',data:<?= json_encode(array_map(fn($r)=>$r['diastolic']!==null?(float)$r['diastolic']:null,$chartRows)) ?>,borderColor:'#6d5bd0',fill:false,spanGaps:true},{label:'Temperature °C',data:<?= json_encode(array_map(fn($r)=>$r['temperature']!==null?(float)$r['temperature']:null,$chartRows)) ?>,borderColor:'#d97706',fill:false,spanGaps:true}]},options:{responsive:true,legend:{position:'bottom'},scales:{yAxes:[{ticks:{beginAtZero:false}}]}}});})();
</script>
